import assert from 'node:assert/strict';
import {createGardenState,stepGarden,restoreGardenState,retryGarden} from '../../../../src/js/garden/GardenSimulation.js';
import {GARDEN as C,GARDEN_WHEELS} from '../../../../src/js/garden/GardenLevel.js';
import {createPilot} from './piloto.mjs';
const irregular=process.argv.includes('--irregular');
for(const difficulty of ['NORMAL','EASY']){
 const state=createGardenState(difficulty);let pilot=createPilot(),previous=state.player.x,idle=0,recovered=0,jumps=0,elapsed=0,retries=0;const visited=new Set();
 for(let tick=0;elapsed<1800&&state.stage!=='COMPLETE';tick++){
  const dt=irregular?[1/120,1/30,.02,.05][tick%4]:1/60;
  elapsed+=dt;if(state.player.support)visited.add(state.player.support);const events=stepGarden(state,pilot(state),dt,difficulty);recovered+=events.filter(e=>e.type==='rescue'||e.type==='dazed').length;jumps+=events.filter(e=>e.type==='jump').length;
  if(state.stage==='GAME_OVER'){if(retries>=3)break;retries++;console.log('REPETIR CHECKPOINT',state.checkpoint,'tempo acumulado',elapsed);assert.ok(retryGarden(state));pilot=createPilot();idle=0;previous=state.player.x;}
  if(Math.abs(state.player.x-previous)<.2)idle+=dt;else idle=0;previous=state.player.x;
  if(tick%18000===0)console.log('PROGRESSO',difficulty,Math.round(state.time),Math.round(state.player.x),state.player.support,state.hp);
  if(idle>18){console.log('BLOQUEIO',JSON.stringify({x:state.player.x,y:state.player.y,support:state.player.support,time:state.time,hp:state.hp}));break;}
 }
 console.log(JSON.stringify({difficulty,irregular,stage:state.stage,minutes:elapsed/60,retries,x:state.player.x,goal:C.goal,hp:state.hp,recovered,jumps,defeated:state.defeated}));
 assert.ok(GARDEN_WHEELS.filter(w=>w.id.startsWith('aerea-')).every(w=>[...visited].some(id=>id.startsWith(w.id+'-'))),'Percorre as três rodas aéreas');assert.ok(visited.has('aereo-ilha-0')&&visited.has('aereo-ilha-1'),'Pisa nas duas ilhas rápidas');
 assert.ok(elapsed/60>4.6&&elapsed/60<5.5,'Duração automatizada próxima de cinco minutos');
 assert.equal(state.stage,'COMPLETE','Percurso contínuo chega ao piquenique');assert.equal(restoreGardenState(JSON.parse(JSON.stringify(state)),difficulty).stage,'COMPLETE');
}
